_idempotency_cache = {}

def send_email_idempotent(to: str, subject: str, body: str, idempotency_key: str) -> dict:
    """Envía email solo si no se envió ya con esa key."""
    cache_key = f"send_email:{idempotency_key}"
    if cache_key in _idempotency_cache:
        # Ya se envió. Devuelve el resultado original.
        return {**_idempotency_cache[cache_key], "idempotent_hit": True}

    # Primer envío — ejecuta de verdad
    message_id = mail_provider.send(to=to, subject=subject, body=body)
    result = {"success": True, "message_id": message_id, "sent_at": now()}
    _idempotency_cache[cache_key] = result
    return result

