def evaluator_optimizer(brief: str, max_rounds: int = 3) -> str:
    draft = generate_initial(brief)
    for round_n in range(max_rounds):
        critique = evaluate(draft, brief)
        if critique["approved"]:
            return draft
        draft = generate_revision(draft, critique["feedback"])
    return draft  # devuelve el último, incluso si no aprobado

def generate_initial(brief: str) -> str:
    return client.messages.create(
        model="claude-sonnet-4-6", max_tokens=600,
        system="Eres un copywriter senior. Escribe el email solicitado.",
        messages=[{"role": "user", "content": brief}]
    ).content[0].text

def evaluate(draft: str, brief: str) -> dict:
    resp = client.messages.create(
        model="claude-sonnet-4-6", max_tokens=400,
        system=(
            "Eres editor crítico. Evalúa si el draft cumple el brief. "
            "Devuelve JSON: {approved: bool, feedback: 'qué mejorar'}"
        ),
        messages=[{"role": "user", "content": f"BRIEF:\n{brief}\n\nDRAFT:\n{draft}"}]
    )
    import json
    return json.loads(resp.content[0].text)

def generate_revision(draft: str, feedback: str) -> str:
    return client.messages.create(
        model="claude-sonnet-4-6", max_tokens=600,
        messages=[{"role": "user",
                   "content": f"Revisa este draft según el feedback:\n\nDRAFT:\n{draft}\n\nFEEDBACK:\n{feedback}"}]
    ).content[0].text

