    ),
    "input_schema": {
        "type": "object",
        "properties": {
            "query": {"type": "string", "description": "Búsqueda en lenguaje natural"},
            "collection": {"type": "string", "enum": ["docs", "incidents", "runbooks"]}
        },
        "required": ["query"]
    }
}

def search_knowledge(query: str, collection: str = "docs", tenant_id: str = None):
    embedding = embed(query)  # OpenAI ada-002 o voyage-3
    rows = conn.execute(
        "SELECT content, source, 1 - (embedding <=> %s) AS score "
        "FROM knowledge WHERE collection = %s AND tenant_id = %s "
        "ORDER BY embedding <=> %s LIMIT 5",
        (embedding, collection, tenant_id, embedding)
    ).fetchall()
    return [{"content": r[0], "source": r[1], "score": r[2]} for r in rows]

