def execute_tool(tool_name: str, args_from_llm: dict, session: Session) -> dict:
    """Ejecuta una tool. tenant_id viene de la sesión, NO del LLM."""
    if tool_name == "search_incidents":
        # El LLM solo pasa query. tenant_id lo inyectamos NOSOTROS.
        return search_incidents(
            query=args_from_llm["query"],
            tenant_id=session.tenant_id  # ← crucial: del contexto, no del modelo
        )
    # Si el LLM intenta especificar tenant_id en args, lo ignoramos:
    if "tenant_id" in args_from_llm:
        log_security_event("LLM tried to set tenant_id", session)
        del args_from_llm["tenant_id"]

from fastapi import FastAPI
from anthropic import Anthropic
import datetime

app = FastAPI()
client = Anthropic()

TOOLS = [{
    "name": "get_current_time",
    "description": "Devuelve la hora actual UTC en ISO 8601.",
    "input_schema": {"type": "object", "properties": {}}
}]

def execute_tool(name: str, args: dict) -> str:
    if name == "get_current_time":
        return datetime.datetime.utcnow().isoformat() + "Z"
    raise ValueError(f"unknown tool {name}")

@app.get("/smoke")
def smoke_test():
    messages = [{"role": "user", "content": "¿Qué hora es?"}]
    while True:
        resp = client.messages.create(
            model="claude-haiku-4-5", max_tokens=512,
            tools=TOOLS, messages=messages
        )
        if resp.stop_reason == "tool_use":
            # Claude pidió usar una tool — ejecutamos
            tool_block = next(b for b in resp.content if b.type == "tool_use")
            result = execute_tool(tool_block.name, tool_block.input)
            messages += [
                {"role": "assistant", "content": resp.content},
                {"role": "user", "content": [{
                    "type": "tool_result",
                    "tool_use_id": tool_block.id,
                    "content": result
                }]}
            ]
            continue
        # Claude respondió final
        return {"answer": resp.content[0].text}
